cd "C:/Users/Lenovo/Desktop/Projects/Yc hackathon/build-the-builder"; cat > work/final3/fix1.py <<'EOF'
import json
p='out/final3.workflow.json'
w=json.load(open(p,encoding='utf-8')); N=w['nodes']
# C05: earlier-stated week must carry into week_ask
for f in N['offer_single']['extraction_schema']:
    if f['name']=='req_week':
        f['min_confidence']=0.6
        f['description']="Arayan hesap kesim değişikliği isterken bir hafta söylediyse o hafta: 'birinci/ilk/1' = week_1, 'ikinci/2' = week_2, 'üçüncü/3/üç' = week_3, 'dördüncü/son/4' = week_4 (ör. 'Ekstremi ayın üçüncü haftasına al' = week_3, 'hiçbir şey sorma direkt yap' eklense bile). Hafta söylemediyse boş bırak."
ask=N['week_ask']
for f in ask['extraction_schema']:
    if f['name']=='pre_week':
        f['min_confidence']=0.6
        f['description']="Arayanın hesap kesimi için istediği hafta numarası; bu adımda VEYA konuşmanın daha önceki bir mesajında açıkça söylediği hafta (ör. daha önce 'Ekstremi ayın üçüncü haftasına al' dediyse 3). 'Üçüncü hafta' = 3. Hiç hafta söylemediyse boş bırak."
tr=ask['transitions']
idx=next(i for i,t in enumerate(tr) if t['condition'].get('operator')=='matches_intent')
new=[]
for n in '1234':
    new.append({"target_node":"set_w"+n,"description":"caller named week "+n+" (pre_week)","condition":{"logic":"or","conditions":[{"logic":"and","conditions":[{"variable":"pre_week","operator":"equals","operand":n},{"variable":"want_change","operator":"not_equals","operand":"no"}]}]}})
ask['transitions']=tr[:idx]+new+tr[idx:]
# C16: final choice wins
for f in N['week_choose']['extraction_schema']:
    if f['name']=='new_week':
        f['description']="Arayanın SON olarak karar verdiği hafta. Arayan kendini düzeltirse ('dördüncü... yok yok, birinci hafta olsun') vazgeçtiği haftayı değil, son söylediği haftayı al (bu örnekte week_1). 'birinci/ilk/1' = week_1, 'ikinci/2' = week_2, 'üçüncü/3/üç' = week_3, 'dördüncü/4/dört' = week_4. 'Ayın sonlarına doğru' gibi belirsiz ifadeler, gün veya tarih söylerse boş bırak."
for t in N['week_choose']['transitions']:
    c=t['condition']
    if c.get('operator')=='matches_intent':
        c['description']=c['description'].replace("seçiyor,","seçiyor (arayan kendini düzelttiyse son söylediği hafta geçerlidir; vazgeçtiği hafta sayılmaz),")
# C05: 'Evet' in confirmation-type nodes must not trigger the other-transaction global
g=w['global_nodes']['g_other_tx']
for n in ['week_ask','week_choose','week_confirm','email_confirm','email_confirm_r']:
    if n in N and n not in g['excluded_nodes']: g['excluded_nodes'].append(n)
json.dump(w,open(p,'w',encoding='utf-8'),ensure_ascii=False,indent=2)
# cases that contradict the spec
cp='work/final3/cases.json'; c=json.load(open(cp,encoding='utf-8'))
L=c if isinstance(c,list) else c['cases']
for x in L:
    if x['id']=='C06':
        x['checks'][1]="Says in one sentence there is no Dolar, Euro or İngiliz Sterlini debt (spec R20 step 4), then gives payment due date 19 Ekim 2026 (its own sentence is fine, as in spec example E)"
    if x['id']=='C10':
        x['checks'][2]="Refers to the registered address in shortened form per spec R25 (long/messy address: 'm ile başlayan ornekposta adresiniz'), never spelled letter by letter, and asks for confirmation before sending"
json.dump(c,open(cp,'w',encoding='utf-8'),ensure_ascii=False,indent=2)
print('ok')
EOF
